# Extract the inner JSON string and parse it, then get all DONE experiment IDs with their conclusion and metrics
cat "$RESULT_FILE" | python3 -c "
import json, sys
outer = json.load(sys.stdin)
inner = json.loads(outer['result'])
exps = inner['data']['experiments']

# Find all SmolVLA tau-sweep related experiments (adaptive_conformal_crm mode with smolvla)
tau_exps = {}
for eid, exp in exps.items():
    # Look for SmolVLA tau-sweep experiments
    if 'smolvla' in eid.lower() and ('tau' in eid.lower() or 'adaptive' in eid.lower()):
        metrics = exp.get('metrics', {})
        conclusion = exp.get('conclusion', '')
        tau_exps[eid] = {'conclusion': conclusion, 'metrics': metrics}
    elif 'tau-sweep' in eid.lower() and 'pi05' not in eid.lower():
        metrics = exp.get('metrics', {})
        conclusion = exp.get('conclusion', '')
        tau_exps[eid] = {'conclusion': conclusion, 'metrics': metrics}
    elif 'eval-tau' in eid.lower():
        metrics = exp.get('metrics', {})
        conclusion = exp.get('conclusion', '')
        tau_exps[eid] = {'conclusion': conclusion, 'metrics': metrics}

# Print sorted
for eid in sorted(tau_exps.keys()):
    m = tau_exps[eid]
    sr = m.get('metrics', {}).get('success_rate', 'N/A') if m.get('metrics') else 'N/A'
    print(f'{eid}: conclusion={m[\"conclusion\"]}, SR={sr}')
